const data = $input.first()?.json ?? {};
const execution = data.execution ?? {};
const trigger = data.trigger ?? {};
const workflowName = String(data.workflow?.name ?? 'Workflow sconosciuto').slice(0, 200);
const error = execution.error ?? trigger.error ?? {};
// Only the error message, truncated: never the stack, node parameters or upstream bodies.
const message = String(error.message ?? 'Errore sconosciuto').slice(0, 500);
const node = String(execution.lastNodeExecuted ?? error.node?.name ?? '—').slice(0, 200);
const url = typeof execution.url === 'string' && execution.url.startsWith('https://') ? execution.url : null;
const when = new Intl.DateTimeFormat('it-IT', { dateStyle: 'short', timeStyle: 'medium', timeZone: 'Europe/Rome' }).format(new Date());
const esc = (s) => s.replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const rows = [
  ['Workflow', workflowName],
  ['Nodo', node],
  ['Errore', message],
  ['Modalità', String(execution.mode ?? (data.trigger ? 'trigger' : '—'))],
  ['Quando', when],
];
const html = '<h2 style="font-family:sans-serif">Workflow n8n fallito</h2>'
  + '<table style="font-family:sans-serif;border-collapse:collapse">'
  + rows.map(([k, v]) => `<tr><td style="padding:4px 12px 4px 0;color:#666">${k}</td><td style="padding:4px 0">${esc(v)}</td></tr>`).join('')
  + '</table>'
  + (url ? `<p style="font-family:sans-serif"><a href="${esc(url)}">Apri l'esecuzione in n8n</a></p>` : '');
return [{ json: { subject: `[n8n] Errore: ${workflowName}`.slice(0, 200), html } }];
